package main

import (
	"bufio"
	"fmt"
	"io"
	"math"
	"os"
	"strconv"
	"strings"
)

var (
	out    = bufio.NewWriter(os.Stdout)
	br     *bufio.Reader
	tokens []string
	tokPos int
)

func readLineTokens() {
	for tokPos >= len(tokens) {
		line, err := br.ReadString('\n')
		if err != nil && err != io.EOF && len(line) == 0 {
			panic(err)
		}
		tokens = strings.Fields(line)
		tokPos = 0
		if err == io.EOF && len(tokens) == 0 {
			break
		}
	}
}

func next() string {
	readLineTokens()
	s := tokens[tokPos]
	tokPos++
	return s
}

func nextInt() int {
	v, _ := strconv.Atoi(next())
	return v
}

func nextLong() int64 {
	v, _ := strconv.ParseInt(next(), 10, 64)
	return v
}

func main() {
	br = bufio.NewReader(os.Stdin)
	defer out.Flush()
	n := nextInt()
	k := nextInt()
	min := math.MaxInt32
	for i := 1; i < k; i++ {
		if n%i == 0 {
			x := (n/(i%k))*k + i
			if x < min {
				min = x
			}
		}
	}
	fmt.Fprint(out, min)
}
